import { ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges } from '@angular/core';
import { MatExpansionModule } from '@angular/material/expansion';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';
import { BadgeComponent } from '../../../../shared/components/badge/badge.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { FactTableComponent } from '../../../../shared/components/fact-table/fact-table.component';
import { WorkspaceService } from '../../../services/workspace/workspace.service';
import { FactfileRes, factissuelistRes, factlistRes, IssuecategoryRes } from '../../../interfaces/workspace.interface';
import { CommonModule } from '@angular/common';
import { SkeletonComponent } from '../../../../shared/components/skeleton/skeleton.component';
import { Subject, Subscription } from 'rxjs';
import { myTeamUsers, toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { finalFilterList } from '../../../../shared/interfaces/filter.interface';
import { MatDialog } from '@angular/material/dialog';
import { CreateissueComponent } from '../../../../realtime/components/issues/createissue/createissue.component';
import { CommonService } from '../../../../shared/services/common/common.service';
import { FactsheetService } from '../../../services/factsheet/factsheet.service';

@Component({
  selector: 'workspace-issues',
  standalone: true,
  imports: [CommonModule, MatExpansionModule, IconComponent, FactTableComponent, EmptyComponent,
    BadgeComponent, ButtonComponent,
    SkeletonComponent],
  templateUrl: './workspace-issues.component.html',
  styleUrl: './workspace-issues.component.scss'
})
export class WorkspaceIssuesComponent implements OnInit, OnChanges, OnDestroy {

  @Input() tablecols: any;
  @Input() nCaseid: string;
  @Input() activetab: string;
  @Input() isFact: boolean;
  @Input() isQFact: boolean;
  @Input() noteSearchText: string = ''; // For highlighting search terms
  @Input() onWorkspaceEvent: Subject<toolEvents>;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() isCritical: boolean;
  @Input() isHeavily: boolean;
  issuelist: any = [];
  visibleIssues: any = [];
  loading: boolean = true;
  jFilter: finalFilterList[] = [];
  userList: myTeamUsers[] = [];
  private workspaceEventSub: Subscription;

  constructor(private readonly wsservice: WorkspaceService, private readonly cdr: ChangeDetectorRef,
    private readonly dialog: MatDialog, private readonly common: CommonService,
    private readonly factsheetService: FactsheetService,
  ) { }

  ngOnInit() {
    this.getIssuelist();
    if (this.onWorkspaceEvent) {
      this.workspaceEventSub = this.onWorkspaceEvent.subscribe((e: toolEvents) => {
        if (e.event === 'FILTER') {
          this.jFilter = e.data;
          this.getIssuelist();
        }
      });
    }
  }

  ngOnDestroy() {
    this.workspaceEventSub?.unsubscribe();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['isHeavily'] || changes['isCritical']) {
      this.sortfact()
    }
    if (this.issuelist.length) {
      this.visibleIssues = this.issuelist.filter(d => d?.jFType ? (d?.jFType).includes(this.isFact ? 'F' : 'QF') : true)
    }
    this.cdr.detectChanges();
  }

  async getteam_list() {
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
  }


  createIssue(x?) {
    const dialog = this.dialog.open(CreateissueComponent, {
      width: '750px',
      height: 'fit-content',
      hasBackdrop: true,
      panelClass: 'noshadow',
      data: { type: x ? 'E' : null, value: x ? x : null, current_session: { nCaseid: this.nCaseid } },
    });
    dialog.componentInstance.isCentered = true;
    dialog.afterClosed().subscribe((result) => {
      if (result?.data) {
        if (result?.data?.nICid !== x.nICid) {
          this.getIssuelist();
        } else {
          x.cIName = result.data.cIName;
          x.cColor = result.data.cColor;
        }
      }
      if (result?.isDeleted) {
        this.getIssuelist();
      }
      this.cdr.detectChanges();
    })
  }

  async getIssuelist() {
    this.loading = true;
    const res: any = await this.wsservice.getIssuelist(this.nCaseid, this.jFilter);
    this.loading = false;
    this.issuelist = this.groupIssueCategory(res);
    if (this.issuelist.length) {
      this.visibleIssues = this.issuelist.filter(d => d?.jFType ? (d?.jFType).includes(this.isFact ? 'F' : 'QF') : true)
    }
    this.cdr.detectChanges();
  }


  groupIssueCategory(issues) {
    const issuecategory: IssuecategoryRes[] = [];
    issues.forEach(element => {
      if (!issuecategory.length) {
        issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, jFType: element.jFType, sublist: [element] });
      } else {
        const index = issuecategory.findIndex(e => e.nICid === element.nICid);
        if (index > -1) {
          if (issuecategory[index].jFType.length < element.jFType.length) {
            issuecategory[index].jFType = element.jFType;
          }
          issuecategory[index].sublist.push(element);
        } else {
          issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, jFType: element.jFType, sublist: [element] });
        }
      }
    });
    return issuecategory;
  }


  getTypeFilter(list) {
    return list.filter(d => d?.jFType ? (d?.jFType).includes(this.isFact ? 'F' : 'QF') : true);
  }

  async getFactlist(x, nContactid, nIssueid) {
    if (x && x.factlist && x.factlist.length) { return; }
    x.loading = true;
    const res: factlistRes[] = await this.wsservice.getFactlist(this.nCaseid, nContactid, nIssueid, 'ALL', this.jFilter);
    x.loading = false;
    x.factlist = res;

    // Normalized note sort key so Note column sorting works here as in Chronology
    const computeNoteSort = (f: factlistRes) => {
      const base = (f.cFact && f.cFact.trim().length)
        ? f.cFact
        : (Array.isArray(f.jTexts) && f.jTexts.length ? String(f.jTexts[0]) : '');
      f.noteSort = base || '';
    };
    x.factlist.forEach(computeNoteSort);

    this.getIssuels(x, nContactid, nIssueid);
    this.getFactfile(x, nContactid, nIssueid);
  }

  async getIssuels(x, nContactid: string, nIssueid: string) {
    const res: factissuelistRes[] = await this.wsservice.getFactIssuelist(this.nCaseid, nContactid, nIssueid, 'ALL', this.jFilter);

    await Promise.all(x.factlist.map(async element => {
      const issues = res.filter(e => e.nFSid === element.nFSid);
      element.issues = issues;
      this.relavanceImpactFilter(element, issues);

      // Map counts from API response
      element.nContactcount = Number((element as any).nTotalContacts || (element as any).nContactcount || 0);
      element.nTaskcount = Number((element as any).nTotalTasks || (element as any).nTaskcount || 0);
      element.nLinkscount = Number((element as any).nTotalLinks || (element as any).nLinkscount || 0);
    }));

    this.cdr.detectChanges();
  }

  relavanceImpactFilter(fact, issues) {
    if (issues.length) {
      const max = issues.reduce((prev, current) => (prev.nRelevanceseq > current.nRelevanceseq) ? prev : current);
      fact.nRelevancecount = issues.filter(e => e.nRelevanceid === max.nRelevanceid).length;
      fact.cRelevance = max.cRelevance;
    }
    if (issues.length) {
      const max = issues.reduce((prev, current) => (prev.nImpactseq > current.nImpactseq) ? prev : current);
      fact.nImpactcount = issues.filter(e => e.nImpactid === max.nImpactid).length;
      fact.nImpactid = max.nImpactid;
    }
    if (issues.length) {
      fact.issuesSort = issues.map(e => e.cIName || '').join(', ').trim();
    } else {
      fact.issuesSort = '';
    }
    return fact;
  }


  async getFactfile(x, nContactid: string, nIssueid: string) {
    const res: FactfileRes[] = await this.wsservice.getFactfilelist(this.nCaseid, nContactid, nIssueid, 'ALL', this.jFilter);
    x.factlist.forEach(element => {
      const file: FactfileRes[] = res.filter(e => e.nFSid === element.nFSid);
      element.linkfile = file
    });
    this.cdr.detectChanges();
  }


  removeGroup(x) {
    x.isGrouping = false;
    x.groupinglist = [];
  }

  OnTableEvent(e, x) {
    if (e.event === 'SORT') {
      const col = e.data.col;
      const typ = e.data.col.typ === 'A' ? 'asc' : e.data.col.typ === 'D' ? 'desc' : 'G';
      if (typ === 'G') {
        x.isGrouping = true;
        x.groupinglist = [];
        if (col.clmn === 'R' || col.clmn === 'I') {
          for (const n of x.factlist) {
            let obj: any = {};
            if (col.clmn === 'R') {
              x.Groupby = 'Relevance';

              for (const i of n.issues) {
                for (const issue of i.sublist) {
                  if (issue.nRelevanceid) {
                    obj = { id: issue.nRelevanceid, name: issue.cRelevance };
                    if (Object.keys(obj).length) {
                      const ins = x.groupinglist.findIndex(m => m.id === obj.id);
                      if (ins >= 0) {
                        if (x.groupinglist[ins]["factlist"].findIndex(m => m.nFSid === n.nFSid) === -1) {
                          x.groupinglist[ins]["factlist"].push(n);
                        }
                      } else {
                        x.groupinglist.push({ id: obj.id, name: obj.name, factlist: [n] });
                      }
                    }
                  }
                }
              }
            } else if (col.clmn === 'I') {
              x.Groupby = 'Impact';
              for (const i of n.issues) {
                for (const issue of i.sublist) {
                  if (issue.nImpactid) {
                    obj = { id: issue.nImpactid, name: issue.cImpact };
                    if (Object.keys(obj).length) {
                      const ins = x.groupinglist.findIndex(m => m.id === obj.id);
                      if (ins >= 0) {
                        if (x.groupinglist[ins]["factlist"].findIndex(m => m.nFSid === n.nFSid) === -1) {
                          x.groupinglist[ins]["factlist"].push(n);
                        }
                      } else {
                        x.groupinglist.push({ id: obj.id, name: obj.name, factlist: [n] });
                      }
                    }
                  }
                }
              }
            }
          }
        }
        else if (col.clmn === 'F') {
          x.Groupby = 'Level type';
          x.groupinglist = [{
            "id": 1,
            "name": "File level",
            "factlist": []
          }, {
            "id": 2,
            "name": "Text level",
            "factlist": []
          }, {
            "id": 3,
            "name": "Range level",
            "factlist": []
          }];
          for (const n of x.factlist) {
            try {
              if (n.jLinktype.type !== 'F' && n.cType === 'M') {
                if (x.groupinglist[2]["factlist"].findIndex(m => m.nFSid === n.nFSid) === -1) {
                  x.groupinglist[2]["factlist"].push(n);
                }
              } else if (n.jLinktype?.type === 'F' && n.cType === 'M') {
                if (x.groupinglist[0]["factlist"].findIndex(m => m.nFSid === n.nFSid) === -1) {
                  x.groupinglist[0]["factlist"].push(n);
                }
              } else if (n.cType !== 'M') {
                if (x.groupinglist[1]["factlist"].findIndex(m => m.nFSid === n.nFSid) === -1) {
                  x.groupinglist[1]["factlist"].push(n);
                }
              }
            } catch { }
          }
        }
        if (!x.groupinglist.length) {
          x.groupFor = '';
          x.isGrouping = false;
        }
        if (col.clmn === 'F') {
          let isdata: boolean = false
          x.groupinglist.forEach(e => {
            if (e.factlist.length) {
              isdata = true
            }
          });
          x.isGrouping = isdata;
        }
        return;
      }
      const clmn = col.clmn === 'topimpact_ind' ? 'nImpactid' : col.clmn === 'toprelevance_ind' ? 'cRelevance' : col.clmn;
      x.factlist = x.factlist.sort((a, b) => {
        const aRaw = (a as any)[clmn];
        const bRaw = (b as any)[clmn];
        const aVal = aRaw === null || aRaw === undefined ? '' : String(aRaw);
        const bVal = bRaw === null || bRaw === undefined ? '' : String(bRaw);
        if (typ === 'asc') {
          return aVal.localeCompare(bVal);
        } else {
          return bVal.localeCompare(aVal);
        }
      });


    } else if (e.event === 'SUBMIT-NOTE') {
      const int = x.factlist.findIndex(j => j.nFSid === e.data.nFSid)
      if (int > -1) {
        x.factlist[int].jTexts = e.data.jTexts;
      }

    } else {
      this.OnEvent.emit(e);
    }
  }


  sortfact() {
    this.issuelist?.forEach(x => {
      x.sublist?.forEach(e => {
        e.factlist?.sort((a, b) => {
          const aImpact = a?.issues[0]?.['nImpactseq'] ?? Number.MAX_SAFE_INTEGER;
          const bImpact = b?.issues[0]?.['nImpactseq'] ?? Number.MAX_SAFE_INTEGER;
          if (this.isHeavily) {
            return aImpact - bImpact;
          } else {
            return aImpact + bImpact;
          }
        })
      })
    });
    this.issuelist?.forEach(x => {
      x.sublist?.forEach(e => {
        e.factlist?.sort((a, b) => {
          const aRelevance = a?.issues[0]?.['nRelevanceseq'] ?? Number.MAX_SAFE_INTEGER;
          const bRelevance = b?.issues[0]?.['nRelevanceseq'] ?? Number.MAX_SAFE_INTEGER;
          if (this.isCritical) {
            return aRelevance - bRelevance;
          } else {
            return aRelevance + bRelevance;
          }
        })
      })
    });
  }
}
